INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000690', 'Wireline logging adalah kegiatan merekam...', 'Wireline logging is the activity of recording...', 'option', 'PFC000000004', 'Inisialisasi', 'a:4:{i:0;s:50:"Sifat fisik batuan terhadap kedalaman lubang sumur";i:1;s:19:"Harga minyak harian";i:2;s:21:"Jumlah pekerja di rig";i:3;s:24:"Volume lumpur pengeboran";}', 'a:4:{i:0;s:46:"Rock physical properties versus borehole depth";i:1;s:16:"Daily oil prices";i:2;s:32:"The number of workers on the rig";i:3;s:19:"Drilling mud volume";}', '', 'Sifat fisik batuan terhadap kedalaman lubang sumur', 'Rock physical properties versus borehole depth', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000691', 'Log gamma ray umumnya digunakan untuk...', 'The gamma ray log is generally used to...', 'option', 'PFC000000004', 'Inisialisasi', 'a:4:{i:0;s:62:"Mengukur radioaktivitas alami batuan sebagai indikator lempung";i:1;s:28:"Mengukur resistivitas fluida";i:2;s:24:"Mengukur porositas total";i:3;s:24:"Mengukur densitas fluida";}', 'a:4:{i:0;s:65:"Measure the natural radioactivity of the rock as a clay indicator";i:1;s:25:"Measure fluid resistivity";i:2;s:22:"Measure total porosity";i:3;s:21:"Measure fluid density";}', '', 'Mengukur radioaktivitas alami batuan sebagai indikator lempung', 'Measure the natural radioactivity of the rock as a clay indicator', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
