INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000693', 'Density log (RHOB) mengukur...', 'The density log (RHOB) measures...', 'option', 'PFC000000004', 'Inisialisasi', 'a:4:{i:0;s:21:"Densitas bulk formasi";i:1;s:30:"Densitas fluida reservoir saja";i:2;s:20:"Resistivitas formasi";i:3;s:22:"Kecepatan suara batuan";}', 'a:4:{i:0;s:22:"Formation bulk density";i:1;s:28:"Reservoir fluid density only";i:2;s:21:"Formation resistivity";i:3;s:22:"Rock acoustic velocity";}', '', 'Densitas bulk formasi', 'Formation bulk density', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000694', 'Neutron log terutama digunakan untuk mengukur...', 'The neutron log is primarily used to measure...', 'option', 'PFC000000004', 'Inisialisasi', 'a:4:{i:0;s:36:"Porositas melalui kandungan hidrogen";i:1;s:15:"Kedalaman sumur";i:2;s:17:"Tekanan reservoir";i:3;s:12:"Kadar sulfur";}', 'a:4:{i:0;s:33:"Porosity through hydrogen content";i:1;s:10:"Well depth";i:2;s:18:"Reservoir pressure";i:3;s:14:"Sulfur content";}', '', 'Porositas melalui kandungan hidrogen', 'Porosity through hydrogen content', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
