INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000696', 'Log SP (spontaneous potential) paling berguna untuk...', 'The SP (spontaneous potential) log is most useful for...', 'option', 'PFC000000004', 'Inisialisasi', 'a:4:{i:0;s:46:"Mendeteksi lapisan permeabel dan menentukan Rw";i:1;s:42:"Mengukur porositas efektif secara langsung";i:2;s:25:"Mengukur densitas matriks";i:3;s:25:"Menentukan kekuatan semen";}', 'a:4:{i:0;s:43:"Detecting permeable beds and determining Rw";i:1;s:37:"Directly measuring effective porosity";i:2;s:24:"Measuring matrix density";i:3;s:27:"Determining cement strength";}', '', 'Mendeteksi lapisan permeabel dan menentukan Rw', 'Detecting permeable beds and determining Rw', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000697', 'Log apa saja yang umum dipakai untuk estimasi porositas?', 'Which logs are commonly used to estimate porosity?', 'multi', 'PFC000000004', 'Inisialisasi', 'a:4:{i:0;s:11:"Density log";i:1;s:11:"Neutron log";i:2;s:9:"Sonic log";i:3;s:13:"Gamma ray log";}', 'a:4:{i:0;s:11:"Density log";i:1;s:11:"Neutron log";i:2;s:9:"Sonic log";i:3;s:13:"Gamma ray log";}', '', 'a:3:{i:0;s:11:"Density log";i:1;s:11:"Neutron log";i:2;s:9:"Sonic log";}', 'a:3:{i:0;s:11:"Density log";i:1;s:11:"Neutron log";i:2;s:9:"Sonic log";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000698', 'Urutkan nilai resistivitas formasi dari yang paling rendah ke paling tinggi.', 'Arrange formation resistivity values from lowest to highest.', 'drag', 'PFC000000004', 'Inisialisasi', 'a:4:{i:0;s:16:"Air asin (brine)";i:1;s:9:"Air tawar";i:2;s:6:"Minyak";i:3;s:3:"Gas";}', 'a:4:{i:0;s:5:"Brine";i:1;s:11:"Fresh water";i:2;s:3:"Oil";i:3;s:3:"Gas";}', '', 'a:4:{i:0;s:16:"Air asin (brine)";i:1;s:9:"Air tawar";i:2;s:6:"Minyak";i:3;s:3:"Gas";}', 'a:4:{i:0;s:5:"Brine";i:1;s:11:"Fresh water";i:2;s:3:"Oil";i:3;s:3:"Gas";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000699', 'Benarkah nilai gamma ray yang tinggi menandakan zona reservoir yang bersih?', 'Is it true that a high gamma ray value indicates a clean reservoir zone?', 'yesorno', 'PFC000000004', 'Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000700', 'Diketahui RHOB 2,20 g/cc, densitas matriks 2,65 g/cc, densitas fluida 1,00 g/cc. Berapa porositas densitas (φD)?', 'Given RHOB 2.20 g/cc, matrix density 2.65 g/cc, and fluid density 1.00 g/cc. What is the density porosity (φD)?', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:5:"18,2%";i:1;s:5:"27,3%";i:2;s:5:"33,3%";i:3;s:5:"45,0%";}', 'a:4:{i:0;s:5:"18.2%";i:1;s:5:"27.3%";i:2;s:5:"33.3%";i:3;s:5:"45.0%";}', '', '27,3%', '27.3%', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000701', 'Efek crossover antara kurva neutron dan density yang saling menjauh biasanya menandakan...', 'The crossover effect between diverging neutron and density curves usually indicates...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:23:"Adanya gas (gas effect)";i:1;s:15:"Adanya air asin";i:2;s:13:"Batuan serpih";i:3;s:20:"Kerusakan lubang bor";}', 'a:4:{i:0;s:32:"The presence of gas (gas effect)";i:1;s:21:"The presence of brine";i:2;s:10:"Shale rock";i:3;s:15:"Borehole damage";}', '', 'Adanya gas (gas effect)', 'The presence of gas (gas effect)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000702', 'Indeks gamma ray (IGR) dihitung dengan persamaan...', 'The gamma ray index (IGR) is calculated by the equation...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:30:"(GR - GRmin) / (GRmax - GRmin)";i:1;s:17:"(GRmax - GR) / GR";i:2;s:20:"(GRmin + GR) / GRmax";i:3;s:17:"GR / GRmax × 100";}', 'a:4:{i:0;s:30:"(GR - GRmin) / (GRmax - GRmin)";i:1;s:17:"(GRmax - GR) / GR";i:2;s:20:"(GRmin + GR) / GRmax";i:3;s:17:"GR / GRmax × 100";}', '', '(GR - GRmin) / (GRmax - GRmin)', '(GR - GRmin) / (GRmax - GRmin)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000703', 'Log induksi (induction log) paling tepat digunakan pada...', 'The induction log is most appropriate for use in...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:59:"Lubang bor berisi lumpur berbasis minyak atau lubang kosong";i:1;s:26:"Lubang bor berisi air asin";i:2;s:30:"Lubang bor yang sangat dangkal";i:3;s:22:"Sumur yang belum dibor";}', 'a:4:{i:0;s:39:"Wells with oil-based mud or empty holes";i:1;s:23:"Wells filled with brine";i:2;s:22:"Very shallow boreholes";i:3;s:30:"Wells that are not drilled yet";}', '', 'Lubang bor berisi lumpur berbasis minyak atau lubang kosong', 'Wells with oil-based mud or empty holes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000704', 'Caliper log digunakan untuk...', 'The caliper log is used to...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:51:"Mengukur diameter lubang bor dan mendeteksi washout";i:1;s:26:"Mengukur porositas efektif";i:2;s:33:"Mengukur resistivitas air formasi";i:3;s:28:"Menentukan jenis hidrokarbon";}', 'a:4:{i:0;s:45:"Measure borehole diameter and detect washouts";i:1;s:26:"Measure effective porosity";i:2;s:35:"Measure formation water resistivity";i:3;s:30:"Determine the hydrocarbon type";}', '', 'Mengukur diameter lubang bor dan mendeteksi washout', 'Measure borehole diameter and detect washouts', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000705', 'Kurva SP yang terdefleksi ke kiri (negatif) relatif terhadap baseline serpih umumnya menandakan...', 'An SP curve deflected to the left (negative) relative to the shale baseline generally indicates...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:68:"Zona permeabel dengan salinitas air formasi lebih tinggi dari lumpur";i:1;s:17:"Zona serpih tebal";i:2;s:38:"Zona dengan resistivitas sangat tinggi";i:3;s:17:"Zona tanpa fluida";}', 'a:4:{i:0;s:66:"A permeable zone with formation water salinity higher than the mud";i:1;s:18:"A thick shale zone";i:2;s:31:"A zone of very high resistivity";i:3;s:20:"A zone without fluid";}', '', 'Zona permeabel dengan salinitas air formasi lebih tinggi dari lumpur', 'A permeable zone with formation water salinity higher than the mud', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000706', 'Micro-resistivity log (MSFL) digunakan untuk menentukan...', 'The micro-resistivity log (MSFL) is used to determine...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:31:"Resistivitas zona flushed (Rxo)";i:1;s:25:"Resistivitas batuan induk";i:2;s:16:"Densitas matriks";i:3;s:21:"Kedalaman total sumur";}', 'a:4:{i:0;s:30:"Flushed zone resistivity (Rxo)";i:1;s:23:"Source rock resistivity";i:2;s:14:"Matrix density";i:3;s:16:"Total well depth";}', '', 'Resistivitas zona flushed (Rxo)', 'Flushed zone resistivity (Rxo)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000707', 'Faktor fotolistrik (PEF) sangat berguna untuk...', 'The photoelectric factor (PEF) is very useful for...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:44:"Identifikasi litologi (jenis mineral batuan)";i:1;s:28:"Menentukan viskositas minyak";i:2;s:24:"Mengukur laju alir sumur";i:3;s:23:"Menentukan tekanan pori";}', 'a:4:{i:0;s:44:"Lithology identification (rock mineral type)";i:1;s:25:"Determining oil viscosity";i:2;s:24:"Measuring well flow rate";i:3;s:25:"Determining pore pressure";}', '', 'Identifikasi litologi (jenis mineral batuan)', 'Lithology identification (rock mineral type)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000708', 'Persamaan Wyllie time-average pada sonic log digunakan untuk...', 'The Wyllie time-average equation on the sonic log is used to...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:48:"Menghitung porositas dari waktu tempuh gelombang";i:1;s:27:"Menghitung resistivitas air";i:2;s:31:"Menghitung saturasi hidrokarbon";i:3;s:28:"Mengukur diameter lubang bor";}', 'a:4:{i:0;s:44:"Calculate porosity from acoustic travel time";i:1;s:27:"Calculate water resistivity";i:2;s:32:"Calculate hydrocarbon saturation";i:3;s:25:"Measure borehole diameter";}', '', 'Menghitung porositas dari waktu tempuh gelombang', 'Calculate porosity from acoustic travel time', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
