INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000710', 'Hukum Archie digunakan untuk menghitung...', 'Archie''s law is used to calculate...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:38:"Saturasi air dari resistivitas formasi";i:1;s:23:"Porositas dari densitas";i:2;s:31:"Permeabilitas dari ukuran butir";i:3;s:27:"Kedalaman dari waktu tempuh";}', 'a:4:{i:0;s:43:"Water saturation from formation resistivity";i:1;s:21:"Porosity from density";i:2;s:28:"Permeability from grain size";i:3;s:22:"Depth from travel time";}', '', 'Saturasi air dari resistivitas formasi', 'Water saturation from formation resistivity', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
