INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000712', 'Manakah faktor yang memengaruhi kualitas pengukuran log?', 'Which factors affect log measurement quality?', 'multi', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:37:"Kondisi lubang bor (washout, mudcake)";i:1;s:29:"Jenis lumpur dan salinitasnya";i:2;s:17:"Kecepatan logging";i:3;s:25:"Warna batuan di permukaan";}', 'a:4:{i:0;s:37:"Borehole condition (washout, mudcake)";i:1;s:21:"Mud type and salinity";i:2;s:13:"Logging speed";i:3;s:25:"Rock color at the surface";}', '', 'a:3:{i:0;s:37:"Kondisi lubang bor (washout, mudcake)";i:1;s:29:"Jenis lumpur dan salinitasnya";i:2;s:17:"Kecepatan logging";}', 'a:3:{i:0;s:37:"Borehole condition (washout, mudcake)";i:1;s:21:"Mud type and salinity";i:2;s:13:"Logging speed";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
